/* eslint-disable @typescript-eslint/no-require-imports -- Metro bundles images via require() */
import { useColorScheme, type ImageSourcePropType } from 'react-native';

/** Bloom logo PNGs, generated by packages/brand/scripts/export-icons.mjs. */
export const appIcon: ImageSourcePropType = require('../../assets/icon.png');
/** Infinity mark with a dark padlock (for light backgrounds). */
export const logoMark: ImageSourcePropType = require('../../assets/splash-icon.png');
/** Same mark with a light padlock (for dark backgrounds). */
export const logoMarkDark: ImageSourcePropType = require('../../assets/splash-icon-dark.png');

/** The mark that stays readable on the current theme background. */
export function useLogoMark(): ImageSourcePropType {
  return useColorScheme() === 'dark' ? logoMarkDark : logoMark;
}
